import{_ as i,o as r,c as t,a2 as a}from"./chunks/framework.y1bVONfd.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function s(n,e,l,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>CardputerZero is a credit-card sized Linux computer built around the Raspberry Pi Compute Module Zero, designed for hackers, developers, and tinkerers.</p><h2 id="what-is-cardputerzero" tabindex="-1">What is CardputerZero? <a class="header-anchor" href="#what-is-cardputerzero" aria-label="Permalink to &quot;What is CardputerZero?&quot;">​</a></h2><p>A pocket-sized, all-in-one gadget featuring:</p><ul><li><strong>Quad-core ARM Cortex-A53</strong> @ 1.0 GHz with 512MB RAM</li><li><strong>1.9&quot; IPS LCD</strong> (320×170) with hardware PWM backlight</li><li><strong>46-key keyboard</strong> with function keys and modifiers</li><li><strong>Full Linux</strong> (Raspberry Pi OS based)</li><li><strong>Rich I/O</strong>: 2× USB-C, USB-A, RJ45 Ethernet, HDMI, Grove, GPIO header</li><li><strong>Audio</strong>: I2S codec, 1W speaker, MEMS mic, 3.5mm jack</li><li><strong>Wireless</strong>: WiFi 802.11bgn + Bluetooth 4.2 BLE</li><li><strong>1500mAh battery</strong> with BQ27220 fuel gauge</li></ul><h2 id="who-is-this-for" tabindex="-1">Who is this for? <a class="header-anchor" href="#who-is-this-for" aria-label="Permalink to &quot;Who is this for?&quot;">​</a></h2><ul><li><strong>Developers</strong> building LVGL/SDL2/Qt apps for embedded Linux</li><li><strong>Hackers</strong> who want a portable Linux terminal with real keys</li><li><strong>Makers</strong> connecting sensors, radios, cameras via GPIO/Grove/HAT</li><li><strong>Students</strong> learning Linux, Python, C on real hardware</li></ul><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><a href="/docs/guide/quick-start.html">Quick Start</a> — Flash and boot in 5 minutes</li><li><a href="/docs/guide/tech-specs.html">Tech Specs</a> — Full hardware specifications</li><li><a href="/docs/software/docker-sdk.html">Build with Docker</a> — Compile apps on any OS</li><li><a href="/docs/software/packaging.html">App Packaging</a> — Create .deb packages for AppStore</li></ul>',9)])])}const p=i(o,[["render",s]]);export{g as __pageData,p as default};
